34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Minimal syntactic check for an email address: a non-empty local part, a single
66	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        LocalDate today = LocalDate.now();
130	        long ownersCreatedToday = this.clinicService.findAllOwners().stream()
131	            .map(Owner::getRegistrationDate)
132	            .filter(today::equals)
133	            .count();
134	        if (ownersCreatedToday >= 100) {
135	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
136	        }
137	        String address = addressNormalizer.normalize(owner.getAddress());
138	        if (address.isBlank()) {
139	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
140	        }
141	        owner.setAddress(address);
142	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
143	        if (telephone == null) {
144	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
145	        }
146	        owner.setTelephone(telephone);
147	        String email = owner.getEmail();
148	        if (email != null) {
149	            email = email.trim();
150	            if (!EMAIL_PATTERN.matcher(email).matches()) {
151	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	            }
153	            owner.setEmail(email.toLowerCase(Locale.ROOT));
154	        }
155	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
156	            .map(Owner::getTelephone)
157	            .filter(Objects::nonNull)
158	            .map(telephoneNormalizer::normalize)
159	            .anyMatch(telephone::equals);
160	        if (telephoneInUse) {
161	            return new ResponseEntity<>(HttpStatus.CONFLICT);
162	        }
163	        String cityKey = normalizeIdentity(owner.getCity());
164	        long ownersInCity = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
166	            .count();
167	        if (ownersInCity >= 50) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        String lastNameKey = normalizeIdentity(owner.getLastName());
171	        String addressKey = addressNormalizer.normalize(owner.getAddress());
172	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
174	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
175	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
176	            if (householdDuplicate) {
177	                return new ResponseEntity<>(HttpStatus.CONFLICT);
178	            }
179	        }
180	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
181	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
182	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
183	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
184	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
185	            .count();
186	        owner.setNamesakeCount(namesakeCount);
187	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
188	        this.clinicService.saveOwner(owner);
189	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
190	        headers.setLocation(UriComponentsBuilder.newInstance()
191	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
192	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    /**
196	     * Normalize a value for household-identity comparison: null becomes an empty
197	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
198	     * to a single space, and the result is lower-cased.
199	     */
200	    private static String normalizeIdentity(String value) {
201	        if (value == null) {
202	            return "";
203	        }
204	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
205	    }
206	
207	    /**
208	     * Build the stable, shared household identifier for an owner, formatted
209	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
210	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
211	     * Owners in the same household (same normalized lastName and address) therefore
212	     * derive an identical householdId.
213	     */
214	    private static String householdId(String lastNameKey, String addressKey) {
215	        String source = lastNameKey + "|" + addressKey;
216	        try {
217	            byte[] digest = MessageDigest.getInstance("SHA-256")
218	                .digest(source.getBytes(StandardCharsets.UTF_8));
219	            StringBuilder sb = new StringBuilder(digest.length * 2);
220	            for (byte b : digest) {
221	                sb.append(String.format("%02x", b));
222	            }
223	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
224	        }
225	        catch (NoSuchAlgorithmException e) {
226	            throw new IllegalStateException("SHA-256 not available", e);
227	        }
228	    }
229	
230	    /**
231	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
232	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
233	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
234	     * sequence equal to one more than the number of owners already in that city
235	     * (e.g. 'LON-SMI-0007').
236	     */
237	    private String nextCustomerCode(String city, String lastName) {
238	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
239	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
240	        String cityKey = normalizeIdentity(city);
241	        int sequence = (int) this.clinicService.findAllOwners().stream()
242	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
243	            .count() + 1;
244	        return String.format("%s-%s-%04d", city3, last3, sequence);
245	    }
246	
247	    /**
248	     * Build the membership number assigned on create, formatted
249	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
250	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
251	     */
252	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
253	        String yy = String.format("%02d", registrationDate.getYear() % 100);
254	        return customerCode + "-M" + yy;
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        currentOwner.setAddress(ownerFieldsDto.getAddress());
265	        currentOwner.setCity(ownerFieldsDto.getCity());
266	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
267	        currentOwner.setLastName(ownerFieldsDto.getLastName());
268	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
269	        this.clinicService.saveOwner(currentOwner);
270	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
271	    }
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Transactional
275	    @Override
276	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner == null) {
279	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	        }
281	        this.clinicService.deleteOwner(owner);
282	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        HttpHeaders headers = new HttpHeaders();
293	        Pet pet = petMapper.toPet(petFieldsDto);
294	        owner.setId(ownerId);
295	        pet.setOwner(owner);
296	        pet.getType().setName(null);
297	        this.clinicService.savePet(pet);
298	        PetDto petDto = petMapper.toPetDto(pet);
299	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
300	            .buildAndExpand(pet.getId()).toUri());
301	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
302	    }
303	
304	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
305	    @Override
306	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
307	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
308	        if (currentOwner != null) {
309	            Pet currentPet = this.clinicService.findPetById(petId);
310	            if (currentPet != null) {
311	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
312	                currentPet.setName(petFieldsDto.getName());
313	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
314	                this.clinicService.savePet(currentPet);
315	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
316	            }
317	        }
318	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
324	        HttpHeaders headers = new HttpHeaders();
325	        Visit visit = visitMapper.toVisit(visitFieldsDto);
326	        Pet pet = new Pet();
327	        pet.setId(petId);
328	        visit.setPet(pet);
329	        this.clinicService.saveVisit(visit);
330	        VisitDto visitDto = visitMapper.toVisitDto(visit);
331	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
332	            .buildAndExpand(visit.getId()).toUri());
333	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
334	    }
335	
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Override
339	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
340	        Owner owner = this.clinicService.findOwnerById(ownerId);
341	        if (owner != null) {
342	            Pet pet = owner.getPet(petId);
343	            if (pet != null) {
344	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
345	            }
346	        }
347	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
348	    }
349	}
